body.script:
(function() {
    const localPart = "contact";
    const domainPart = "shimsystems.com";
    const cleanEmail = localPart + "@" + domainPart;

    const links = ["nav-contact", "hero-email", "contact-box-email"];
    links.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.href = "mailto:" + cleanEmail;
            if (id !== "hero-email") {
                el.textContent = cleanEmail;
            }
        }
    });
})();
